/* ==========================================================================
   BMI Calculator - Modern Health & Wellness UI Stylesheet
   ========================================================================== */

:root {
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --bg-gradient: linear-gradient(135deg, #f0f4f8 0%, #e2e8f0 100%);
  --card-bg: #ffffff;
  --card-border: rgba(226, 232, 240, 0.8);
  --text-main: #1e293b;
  --text-muted: #64748b;
  --text-light: #94a3b8;
  --primary: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-light: #eff6ff;

  /* BMI Category Palette */
  --c-underweight: #3b82f6;
  --c-underweight-bg: #eff6ff;
  --c-normal: #10b981;
  --c-normal-bg: #ecfdf5;
  --c-obese1: #f59e0b;
  --c-obese1-bg: #fffbeb;
  --c-obese2: #f97316;
  --c-obese2-bg: #fff7ed;
  --c-obese3: #ef4444;
  --c-obese3-bg: #fef2f2;
  --c-obese4: #b91c1c;
  --c-obese4-bg: #fdf2f2;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 18px;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background: var(--bg-gradient);
  color: var(--text-main);
  min-height: 100vh;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* Container */
.app-container {
  width: 100%;
  max-width: 1080px;
  margin: 0 auto;
  padding: 24px 16px 48px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* Header */
.header {
  text-align: center;
  padding: 12px 0 6px;
}

.title {
  font-size: 1.85rem;
  font-weight: 800;
  color: #0f172a;
  letter-spacing: -0.02em;
  margin-bottom: 6px;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
  max-width: 580px;
  margin: 0 auto;
  line-height: 1.45;
}

/* Main Grid Layout */
.main-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 860px) {
  .main-grid {
    grid-template-columns: 1.15fr 1.25fr;
    align-items: start;
  }
}

/* Generic Card */
.card {
  background: var(--card-bg);
  border-radius: var(--radius-lg);
  border: 1px solid var(--card-border);
  box-shadow: var(--shadow-md);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.card:hover {
  box-shadow: var(--shadow-lg);
}

.card-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: #0f172a;
  display: flex;
  align-items: center;
  gap: 8px;
  border-bottom: 2px solid #f1f5f9;
  padding-bottom: 12px;
  margin-bottom: 4px;
}

/* Form Controls */
.form-group {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.form-label-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.form-label {
  font-size: 0.95rem;
  font-weight: 600;
  color: #334155;
}

.input-row {
  display: flex;
  align-items: center;
  background: #f8fafc;
  border: 1.5px solid #cbd5e1;
  border-radius: var(--radius-md);
  padding: 4px 12px;
  transition: all 0.2s ease;
}

.input-row:focus-within {
  border-color: var(--primary);
  background: #ffffff;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.number-input {
  border: none;
  background: transparent;
  font-size: 1.25rem;
  font-weight: 700;
  color: #0f172a;
  width: 100px;
  outline: none;
  text-align: right;
  padding: 6px 4px;
}

/* Remove number input spinners */
.number-input::-webkit-outer-spin-button,
.number-input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}
.number-input[type=number] {
  -moz-appearance: textfield;
}

.unit-text {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-muted);
  margin-left: 6px;
  user-select: none;
}

/* Range Slider */
.range-slider {
  width: 100%;
  height: 8px;
  border-radius: 9999px;
  background: #e2e8f0;
  accent-color: var(--primary);
  outline: none;
  transition: opacity 0.2s;
  cursor: pointer;
  -webkit-appearance: none;
  appearance: none;
}

.range-slider::-moz-range-progress {
  background-color: var(--primary);
  border-radius: 9999px;
  height: 8px;
}

.range-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--primary);
  border: 3px solid #ffffff;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.2);
  cursor: pointer;
  transition: transform 0.15s ease, background-color 0.15s ease;
}

.range-slider::-webkit-slider-thumb:hover {
  transform: scale(1.15);
  background: var(--primary-hover);
}

.range-slider::-webkit-slider-thumb:active {
  transform: scale(0.95);
}

.range-slider::-moz-range-thumb {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--primary);
  border: 3px solid #ffffff;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.2);
  cursor: pointer;
}

/* Preset Buttons */
.preset-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 4px;
}

.preset-btn {
  font-size: 0.85rem;
  font-weight: 600;
  color: #475569;
  background: #f1f5f9;
  border: 1px solid #e2e8f0;
  border-radius: 20px;
  padding: 6px 14px;
  cursor: pointer;
  transition: all 0.2s ease;
  user-select: none;
}

.preset-btn:hover {
  background: #e2e8f0;
  color: #1e293b;
}

.preset-btn-active {
  background: var(--primary);
  color: #ffffff;
  border-color: var(--primary);
  box-shadow: 0 2px 6px rgba(37, 99, 235, 0.3);
}

.preset-btn-active:hover {
  background: var(--primary-hover);
  color: #ffffff;
}

.reset-btn {
  align-self: flex-start;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 4px 6px;
  text-decoration: underline;
  transition: color 0.15s ease;
}

.reset-btn:hover {
  color: #0f172a;
}

/* Result Card */
.result-card {
  background: var(--card-bg);
  border-radius: var(--radius-lg);
  border: 1px solid var(--card-border);
  box-shadow: var(--shadow-md);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.result-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

.bmi-score-box {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.bmi-label {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.bmi-value {
  font-size: 3rem;
  font-weight: 900;
  line-height: 1;
  color: #0f172a;
  letter-spacing: -0.03em;
}

.bmi-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.95rem;
  font-weight: 700;
  padding: 8px 18px;
  border-radius: 9999px;
  letter-spacing: 0.01em;
  white-space: nowrap;
}

/* Badge Categories */
.badge-underweight {
  color: #1d4ed8;
  background-color: var(--c-underweight-bg);
  border: 1px solid #bfdbfe;
}

.badge-normal {
  color: #047857;
  background-color: var(--c-normal-bg);
  border: 1px solid #a7f3d0;
}

.badge-obese1 {
  color: #b45309;
  background-color: var(--c-obese1-bg);
  border: 1px solid #fde68a;
}

.badge-obese2 {
  color: #c2410c;
  background-color: var(--c-obese2-bg);
  border: 1px solid #fed7aa;
}

.badge-obese3 {
  color: #b91c1c;
  background-color: var(--c-obese3-bg);
  border: 1px solid #fecaca;
}

.badge-obese4 {
  color: #991b1b;
  background-color: var(--c-obese4-bg);
  border: 1px solid #fca5a5;
}

/* Result Details Grid */
.result-details {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 12px;
  background: #f8fafc;
  padding: 16px;
  border-radius: var(--radius-md);
  border: 1px solid #f1f5f9;
}

.detail-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.detail-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-muted);
}

.detail-value {
  font-size: 1.15rem;
  font-weight: 700;
  color: #1e293b;
}

/* Gauge Meter Component */
.gauge-wrapper {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin: 8px 0;
}

.gauge-bar {
  position: relative;
  display: flex;
  width: 100%;
  height: 18px;
  border-radius: 9999px;
  overflow: visible;
  background: #e2e8f0;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.1);
}

.gauge-segment {
  height: 100%;
  flex-shrink: 0;
  transition: opacity 0.2s ease;
}

.gauge-segment:first-child {
  border-top-left-radius: 9999px;
  border-bottom-left-radius: 9999px;
}

.gauge-segment:last-child {
  border-top-right-radius: 9999px;
  border-bottom-right-radius: 9999px;
}

.gauge-pointer {
  position: absolute;
  top: -6px;
  bottom: -6px;
  width: 5px;
  background: #0f172a;
  border-radius: 3px;
  transform: translateX(-50%);
  box-shadow: 0 0 0 2px #ffffff, 0 2px 6px rgba(0, 0, 0, 0.35);
  transition: left 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
  pointer-events: none;
  z-index: 2;
}

.gauge-pointer::before {
  content: "";
  position: absolute;
  top: -5px;
  left: 50%;
  transform: translateX(-50%);
  border-left: 5px solid transparent;
  border-right: 5px solid transparent;
  border-top: 6px solid #0f172a;
}

.gauge-labels {
  position: relative;
  width: 100%;
  height: 18px;
  margin-top: 2px;
}

.gauge-label-text {
  position: absolute;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--text-light);
  user-select: none;
  white-space: nowrap;
  transform: translateX(-50%);
}

.gauge-label-text:nth-child(1) {
  left: 0%;
  transform: translateX(0);
}

.gauge-label-text:nth-child(2) {
  left: 14%;
}

.gauge-label-text:nth-child(3) {
  left: 28%;
}

.gauge-label-text:nth-child(4) {
  left: 40%;
}

.gauge-label-text:nth-child(5) {
  left: 60%;
}

.gauge-label-text:nth-child(6) {
  left: 80%;
}

.gauge-label-text:nth-child(7) {
  left: 100%;
  transform: translateX(-100%);
}

/* BMI Table Component */
.table-wrapper {
  width: 100%;
  overflow-x: auto;
  border-radius: var(--radius-md);
  border: 1px solid #e2e8f0;
}

.bmi-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  text-align: left;
  font-size: 0.88rem;
  background: #ffffff;
}

.table-head {
  background: #f8fafc;
  color: #475569;
  font-weight: 700;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.table-head th {
  border-bottom: 1.5px solid #e2e8f0;
}

.table-cell {
  padding: 10px 14px;
  vertical-align: middle;
}

.table-row td {
  border-bottom: 1px solid #f1f5f9;
  transition: background-color 0.15s ease;
}

.table-row:last-child td {
  border-bottom: none;
}

.table-row:hover td {
  background-color: #f8fafc;
}

.table-row-active td {
  background-color: #f0fdf4 !important;
  font-weight: 700;
  color: #065f46;
}

.table-badge {
  display: inline-block;
  font-size: 0.78rem;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 9999px;
  white-space: nowrap;
}

/* Print Friendly & Accessibility */
@media print {
  body {
    background: #ffffff;
  }
  .card, .result-card {
    box-shadow: none;
    border: 1px solid #cbd5e1;
  }
}

export type BmiCategoryType =
  | 'underweight'
  | 'normal'
  | 'obese1'
  | 'obese2'
  | 'obese3'
  | 'obese4';

export interface BmiResult {
  bmi: number;
  category: string;
  categoryType: BmiCategoryType;
  standardWeight: number;
  weightDiff: number;
  minNormalWeight: number;
  maxNormalWeight: number;
}

export interface BmiCategoryItem {
  label: string;
  range: string;
  type: BmiCategoryType;
  badgeClass: string;
}

export interface BmiGaugeProps {
  bmi: number;
}

export interface BmiTableProps {
  currentCategoryType: BmiCategoryType;
}

export interface PresetProfile {
  label: string;
  height: number;
  weight: number;
}

export interface InputRangeConstraint {
  inputMin: number;
  inputMax: number;
  sliderMin: number;
  sliderMax: number;
  step: number;
}

export const HEIGHT_CONSTRAINTS: InputRangeConstraint = {
  inputMin: 100,
  inputMax: 230,
  sliderMin: 120,
  sliderMax: 210,
  step: 0.5,
};

export const WEIGHT_CONSTRAINTS: InputRangeConstraint = {
  inputMin: 20,
  inputMax: 200,
  sliderMin: 30,
  sliderMax: 140,
  step: 0.5,
};

import { FC } from 'react';
import { BmiGaugeProps } from '../types';

const MIN_BMI = 15;
const MAX_BMI = 45;

const LABELS = [
  { value: 15, text: '15 (低)', align: 'left' },
  { value: 18.5, text: '18.5', align: 'center' },
  { value: 22, text: '22 (適正)', align: 'center' },
  { value: 25, text: '25', align: 'center' },
  { value: 30, text: '30', align: 'center' },
  { value: 35, text: '35', align: 'center' },
  { value: 40, text: '40', align: 'center' },
  { value: 45, text: '45+ (高)', align: 'right' },
];

const BmiGauge: FC<BmiGaugeProps> = ({ bmi = 22 }) => {
  const safeBmi = typeof bmi === 'number' && !isNaN(bmi) ? bmi : 22;
  const clampedBmi = Math.max(MIN_BMI, Math.min(MAX_BMI, safeBmi));
  const pointerPercent = ((clampedBmi - MIN_BMI) / (MAX_BMI - MIN_BMI)) * 100;

  return (
    <div className="gauge-wrapper">
      <div
        className="gauge-bar"
        role="meter"
        aria-label="BMI指数ゲージ"
        aria-valuenow={clampedBmi}
        aria-valuemin={MIN_BMI}
        aria-valuemax={MAX_BMI}
        aria-valuetext={`BMI ${safeBmi.toFixed(1)}`}
      >
        {/* 各区間の比率 (総幅: 30 BMI単位: 15〜45) */}
        {/* 15 ~ 18.5: 3.5 / 30 = 11.6667% */}
        <div
          className="gauge-segment"
          style={{ width: `${((18.5 - 15) / 30) * 100}%`, backgroundColor: 'var(--c-underweight)' }}
          title="低体重 (<18.5)"
        />
        {/* 18.5 ~ 25: 6.5 / 30 = 21.6667% */}
        <div
          className="gauge-segment"
          style={{ width: `${((25 - 18.5) / 30) * 100}%`, backgroundColor: 'var(--c-normal)' }}
          title="普通体重 (18.5〜25)"
        />
        {/* 25 ~ 30: 5 / 30 = 16.6667% */}
        <div
          className="gauge-segment"
          style={{ width: `${((30 - 25) / 30) * 100}%`, backgroundColor: 'var(--c-obese1)' }}
          title="肥満1度 (25〜30)"
        />
        {/* 30 ~ 35: 5 / 30 = 16.6667% */}
        <div
          className="gauge-segment"
          style={{ width: `${((35 - 30) / 30) * 100}%`, backgroundColor: 'var(--c-obese2)' }}
          title="肥満2度 (30〜35)"
        />
        {/* 35 ~ 40: 5 / 30 = 16.6667% */}
        <div
          className="gauge-segment"
          style={{ width: `${((40 - 35) / 30) * 100}%`, backgroundColor: 'var(--c-obese3)' }}
          title="肥満3度 (35〜40)"
        />
        {/* 40 ~ 45: 5 / 30 = 16.6667% */}
        <div
          className="gauge-segment"
          style={{ width: `${((45 - 40) / 30) * 100}%`, backgroundColor: 'var(--c-obese4)' }}
          title="肥満4度 (40以上)"
        />

        <div
          className="gauge-pointer"
          style={{ left: `${pointerPercent}%` }}
          aria-hidden="true"
        />
      </div>

      <div className="gauge-labels" style={{ position: 'relative', height: '1.25rem' }}>
        {LABELS.map((item) => {
          const percent = ((item.value - MIN_BMI) / (MAX_BMI - MIN_BMI)) * 100;
          const transform =
            item.align === 'left'
              ? 'translateX(0%)'
              : item.align === 'right'
              ? 'translateX(-100%)'
              : 'translateX(-50%)';

          return (
            <span
              key={item.value}
              className="gauge-label-text"
              style={{
                position: 'absolute',
                left: `${percent}%`,
                transform,
                whiteSpace: 'nowrap',
              }}
            >
              {item.text}
            </span>
          );
        })}
      </div>
    </div>
  );
};

export default BmiGauge;

import { FC } from 'react';
import { BmiTableProps, BmiCategoryItem } from '../types';

const CATEGORIES: BmiCategoryItem[] = [
  {
    label: '低体重 (やせ型)',
    range: '18.5 未満',
    type: 'underweight',
    badgeClass: 'badge-underweight',
  },
  {
    label: '普通体重',
    range: '18.5 以上 25.0 未満',
    type: 'normal',
    badgeClass: 'badge-normal',
  },
  {
    label: '肥満（1度）',
    range: '25.0 以上 30.0 未満',
    type: 'obese1',
    badgeClass: 'badge-obese1',
  },
  {
    label: '肥満（2度）',
    range: '30.0 以上 35.0 未満',
    type: 'obese2',
    badgeClass: 'badge-obese2',
  },
  {
    label: '肥満（3度）',
    range: '35.0 以上 40.0 未満',
    type: 'obese3',
    badgeClass: 'badge-obese3',
  },
  {
    label: '肥満（4度）',
    range: '40.0 以上',
    type: 'obese4',
    badgeClass: 'badge-obese4',
  },
];

const BmiTable: FC<BmiTableProps> = ({ currentCategoryType }) => {
  return (
    <div className="card">
      <h3 className="card-title">
        <span>📋</span> 日本肥満学会の判定基準
      </h3>
      <div className="table-wrapper">
        <table className="bmi-table">
          <thead className="table-head">
            <tr>
              <th className="table-cell">判定区分</th>
              <th className="table-cell">BMI範囲</th>
              <th className="table-cell">状況</th>
            </tr>
          </thead>
          <tbody>
            {CATEGORIES.map((cat) => {
              const isActive = cat.type === currentCategoryType;
              const rowClassName = isActive ? 'table-row table-row-active' : 'table-row';
              const badgeClassName = `table-badge ${cat.badgeClass}`;

              return (
                <tr
                  key={cat.type}
                  className={rowClassName}
                  aria-current={isActive ? 'true' : undefined}
                >
                  <td className="table-cell">
                    <span className={badgeClassName}>{cat.label}</span>
                  </td>
                  <td className="table-cell">{cat.range}</td>
                  <td className="table-cell">
                    {isActive ? (
                      <span
                        style={{
                          display: 'inline-flex',
                          alignItems: 'center',
                          gap: '4px',
                          fontWeight: 700,
                        }}
                      >
                        <span aria-hidden="true">✓</span> 現在の判定
                      </span>
                    ) : (
                      <span aria-label="該当なし">-</span>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default BmiTable;

import { useState, useMemo, ChangeEvent } from 'react';
import { PresetProfile } from './types';
import BmiGauge from './components/BmiGauge';
import BmiTable from './components/BmiTable';
import {
  MIN_HEIGHT,
  MAX_HEIGHT,
  STEP_HEIGHT,
  MIN_WEIGHT,
  MAX_WEIGHT,
  STEP_WEIGHT,
  DEFAULT_HEIGHT,
  DEFAULT_WEIGHT,
  calculateBmi,
  getBadgeClassName,
} from './utils/bmi';

const PRESETS: PresetProfile[] = [
  { label: '標準体型 (成人男性目安)', height: 171, weight: 64.3 },
  { label: '標準体型 (成人女性目安)', height: 158, weight: 54.9 },
  { label: 'やせ型モデル体型', height: 165, weight: 47.0 },
  { label: '筋肉質・がっしり体型', height: 175, weight: 80.0 },
];

export default function App() {
  const [heightInput, setHeightInput] = useState<string | number>(DEFAULT_HEIGHT);
  const [weightInput, setWeightInput] = useState<string | number>(DEFAULT_WEIGHT);

  const numericHeight = useMemo(() => {
    const val = typeof heightInput === 'number' ? heightInput : parseFloat(heightInput);
    if (isNaN(val)) return DEFAULT_HEIGHT;
    return Math.max(MIN_HEIGHT, Math.min(MAX_HEIGHT, val));
  }, [heightInput]);

  const numericWeight = useMemo(() => {
    const val = typeof weightInput === 'number' ? weightInput : parseFloat(weightInput);
    if (isNaN(val)) return DEFAULT_WEIGHT;
    return Math.max(MIN_WEIGHT, Math.min(MAX_WEIGHT, val));
  }, [weightInput]);

  const result = useMemo(
    () => calculateBmi(numericHeight, numericWeight),
    [numericHeight, numericWeight]
  );

  const handleHeightInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    setHeightInput(e.target.value);
  };

  const handleHeightSliderChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setHeightInput(val);
  };

  const handleHeightBlur = () => {
    const val = parseFloat(String(heightInput));
    if (isNaN(val)) {
      setHeightInput(DEFAULT_HEIGHT);
    } else {
      setHeightInput(Math.max(MIN_HEIGHT, Math.min(MAX_HEIGHT, val)));
    }
  };

  const handleWeightInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    setWeightInput(e.target.value);
  };

  const handleWeightSliderChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setWeightInput(val);
  };

  const handleWeightBlur = () => {
    const val = parseFloat(String(weightInput));
    if (isNaN(val)) {
      setWeightInput(DEFAULT_WEIGHT);
    } else {
      setWeightInput(Math.max(MIN_WEIGHT, Math.min(MAX_WEIGHT, val)));
    }
  };

  const applyPreset = (pHeight: number, pWeight: number) => {
    setHeightInput(pHeight);
    setWeightInput(pWeight);
  };

  const handleReset = () => {
    setHeightInput(DEFAULT_HEIGHT);
    setWeightInput(DEFAULT_WEIGHT);
  };

  const badgeClass = getBadgeClassName(result.categoryType);
  const formattedWeightDiff =
    result.weightDiff > 0
      ? `+${result.weightDiff} kg (適正より重い)`
      : result.weightDiff < 0
      ? `${result.weightDiff} kg (適正より軽い)`
      : '0.0 kg (ぴったり適正)';

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">BMI・適正体重 判定ツール</h1>
        <p className="subtitle">
          身長と体重を入力するだけでBMI、適正体重、肥満度レベルをリアルタイムに計算します。
        </p>
      </header>

      <main className="main-grid">
        {/* 入力パネル */}
        <section className="card">
          <h2 className="card-title">
            <span>📏</span> 体型データの入力
          </h2>

          {/* 身長入力 */}
          <div className="form-group">
            <div className="form-label-row">
              <label htmlFor="height-input" className="form-label">
                身長
              </label>
              <div className="input-row">
                <input
                  id="height-input"
                  type="number"
                  min={MIN_HEIGHT}
                  max={MAX_HEIGHT}
                  step={STEP_HEIGHT}
                  value={heightInput}
                  onChange={handleHeightInputChange}
                  onBlur={handleHeightBlur}
                  className="number-input"
                  aria-label="身長(cm)"
                />
                <span className="unit-text">cm</span>
              </div>
            </div>
            <input
              id="height-slider"
              type="range"
              min={MIN_HEIGHT}
              max={MAX_HEIGHT}
              step={STEP_HEIGHT}
              value={numericHeight}
              onChange={handleHeightSliderChange}
              className="range-slider"
              aria-label="身長スライダー"
            />
          </div>

          {/* 体重入力 */}
          <div className="form-group">
            <div className="form-label-row">
              <label htmlFor="weight-input" className="form-label">
                体重
              </label>
              <div className="input-row">
                <input
                  id="weight-input"
                  type="number"
                  min={MIN_WEIGHT}
                  max={MAX_WEIGHT}
                  step={STEP_WEIGHT}
                  value={weightInput}
                  onChange={handleWeightInputChange}
                  onBlur={handleWeightBlur}
                  className="number-input"
                  aria-label="体重(kg)"
                />
                <span className="unit-text">kg</span>
              </div>
            </div>
            <input
              id="weight-slider"
              type="range"
              min={MIN_WEIGHT}
              max={MAX_WEIGHT}
              step={STEP_WEIGHT}
              value={numericWeight}
              onChange={handleWeightSliderChange}
              className="range-slider"
              aria-label="体重スライダー"
            />
          </div>

          {/* プリセット選択 */}
          <div className="form-group">
            <span className="form-label">代表的な体型プリセット</span>
            <div className="preset-buttons">
              {PRESETS.map((p) => {
                const isActive = numericHeight === p.height && numericWeight === p.weight;
                const btnClass = isActive ? 'preset-btn preset-btn-active' : 'preset-btn';
                return (
                  <button
                    key={p.label}
                    type="button"
                    className={btnClass}
                    onClick={() => applyPreset(p.height, p.weight)}
                  >
                    {p.label} ({p.height}cm / {p.weight}kg)
                  </button>
                );
              })}
            </div>
          </div>

          <button type="button" className="reset-btn" onClick={handleReset}>
            標準値にリセット
          </button>
        </section>

        {/* 結果表示パネル */}
        <section className="result-card">
          <div className="result-header">
            <div className="bmi-score-box">
              <span className="bmi-label">判定結果 BMI指数</span>
              <span className="bmi-value">{result.bmi.toFixed(1)}</span>
            </div>
            <div className={badgeClass}>{result.category}</div>
          </div>

          {/* 視覚的メーター */}
          <BmiGauge bmi={result.bmi} />

          {/* 詳細内訳 */}
          <div className="result-details">
            <div className="detail-item">
              <span className="detail-label">適正体重 (BMI 22)</span>
              <span className="detail-value">{result.standardWeight.toFixed(1)} kg</span>
            </div>
            <div className="detail-item">
              <span className="detail-label">適正体重との差</span>
              <span className="detail-value">{formattedWeightDiff}</span>
            </div>
            <div className="detail-item">
              <span className="detail-label">普通体重の範囲</span>
              <span className="detail-value">
                {result.minNormalWeight.toFixed(1)} 〜 {result.maxNormalWeight.toFixed(1)} kg
              </span>
            </div>
          </div>
        </section>
      </main>

      {/* 基準値テーブル */}
      <BmiTable currentCategoryType={result.categoryType} />
    </div>
  );
}

import { BmiCategoryType, BmiResult } from '../types';

export const MIN_HEIGHT = 100;
export const MAX_HEIGHT = 230;
export const STEP_HEIGHT = 0.5;

export const MIN_WEIGHT = 20;
export const MAX_WEIGHT = 200;
export const STEP_WEIGHT = 0.5;

export const DEFAULT_HEIGHT = 170;
export const DEFAULT_WEIGHT = 63.6;

export function calculateBmi(heightCm: number, weightKg: number): BmiResult {
  const heightM = heightCm / 100;
  const rawBmi = heightM > 0 ? weightKg / (heightM * heightM) : 0;
  const bmi = Math.round(rawBmi * 10) / 10;

  // 適正体重 (BMI 22)
  const standardWeight = Math.round(22 * heightM * heightM * 10) / 10;
  const weightDiff = Math.round((weightKg - standardWeight) * 10) / 10;

  // 普通体重の範囲 (BMI 18.5 〜 25.0)
  const minNormalWeight = Math.round(18.5 * heightM * heightM * 10) / 10;
  const maxNormalWeight = Math.round(25.0 * heightM * heightM * 10) / 10;

  let category = '普通体重';
  let categoryType: BmiCategoryType = 'normal';

  if (bmi < 18.5) {
    category = '低体重 (やせ型)';
    categoryType = 'underweight';
  } else if (bmi < 25.0) {
    category = '普通体重';
    categoryType = 'normal';
  } else if (bmi < 30.0) {
    category = '肥満（1度）';
    categoryType = 'obese1';
  } else if (bmi < 35.0) {
    category = '肥満（2度）';
    categoryType = 'obese2';
  } else if (bmi < 40.0) {
    category = '肥満（3度）';
    categoryType = 'obese3';
  } else {
    category = '肥満（4度）';
    categoryType = 'obese4';
  }

  return {
    bmi,
    category,
    categoryType,
    standardWeight,
    weightDiff,
    minNormalWeight,
    maxNormalWeight,
  };
}

export function getBadgeClassName(categoryType: BmiCategoryType): string {
  switch (categoryType) {
    case 'underweight':
      return 'bmi-badge badge-underweight';
    case 'normal':
      return 'bmi-badge badge-normal';
    case 'obese1':
      return 'bmi-badge badge-obese1';
    case 'obese2':
      return 'bmi-badge badge-obese2';
    case 'obese3':
      return 'bmi-badge badge-obese3';
    case 'obese4':
      return 'bmi-badge badge-obese4';
  }
}
